  ["abilities","spells","tricks","modifications","anomalies","rollHistory","immunities","resistances"].forEach(k=>s[k]=Array.isArray(incoming[k])?incoming[k]:base[k]);
  s.abilities=s.abilities.map(x=>({...x,type:x.type==="Ataque"||num(incoming.schemaVersion)<3&&x.type==="Ativa"?"Técnica":(ABILITY_TYPES.includes(x.type)?x.type:"Técnica"),level:ABILITY_LEVELS.includes(x.level)?x.level:"Comum",enabled:Boolean(x.enabled),effectMode:x.effectMode||(x.type==="Passiva"?"always":"whenEnabled"),attributeBonuses:Array.isArray(x.attributeBonuses)?x.attributeBonuses:[],statusBonuses:normalizeStatusBonuses(x.statusBonuses),resistances:normalizeResistances(x.resistances),immunities:normalizeImmunities(x.immunities),attack:normalizeAttack(x.attack)}));
  s.spells=s.spells.map(normalizeSpell);
  s.tricks=s.tricks.map(normalizeTrick);
  s.anomalies=s.anomalies.map(x=>({...x,polarity:x.polarity||"Negativa",origin:x.origin||"",duration:x.duration||"",intensity:x.intensity||"",nature:x.nature||"",effects:(x.effects||[]).map(e=>({...e,mode:e.mode||"percent",value:e.value!==undefined?num(e.value):num(e.percent)}))}));
  s.modifications=s.modifications.map(x=>({...x,enabled:x.enabled!==false,activatable:x.activatable!==false,attributeBonuses:Array.isArray(x.attributeBonuses)?x.attributeBonuses:[],statusBonuses:normalizeStatusBonuses(x.statusBonuses),resistances:normalizeResistances(x.resistances),immunities:normalizeImmunities(x.immunities)}));
  s.inventory.equipment=(s.inventory.equipment||[]).map(x=>({...x,type:x.type||"Item comum",tier:LEGACY_PATAMAR[x.tier]||x.tier||"Desperto",weight:num(x.weight),quantity:Math.max(1,num(x.quantity)||1),value:x.value??null,equipped:Boolean(x.equipped),effects:x.effects||"",grantedAbilities:x.grantedAbilities||"",attributeBonuses:Array.isArray(x.attributeBonuses)?x.attributeBonuses:[],statusBonuses:normalizeStatusBonuses(x.statusBonuses),resistances:normalizeResistances(x.resistances),immunities:normalizeImmunities(x.immunities),attack:normalizeAttack(x.attack)}));
