  if(incoming.status?.initiativeBonus===undefined)s.status.initiativeBonus=incoming.status?.initiative===undefined?0:num(incoming.status.initiative)-legacyAttrs.destreza;
  s.status.traumaBaseMax=SYSTEM_CONFIG.traumaLimit;
