function save(){clearTimeout(saveTimer);document.getElementById("saveStatus").textContent="Salvando…";saveTimer=setTimeout(()=>{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));document.getElementById("saveStatus").textContent="Salvo"},180)}
function commit(render=true){state.schemaVersion=SCHEMA_VERSION;syncCombatStateFor(state);save();if(render)renderApp()}
function esc(v){return String(v??"").replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]))}
function num(v){const n=Number(v);return Number.isFinite(n)?n:0}
function clamp(n,min,max){return Math.min(max,Math.max(min,num(n)))}
function resourcePercent(current,max){const maximum=num(max);return maximum>0?clamp(num(current)/maximum*100,0,100):0}
function normalizeAction(action){if(action==="Movimento")return "Ação de Movimento";if(action==="Sustentação")return "Ação Padrão";return [...ACTIONS,"Ação Completa"].includes(action)?action:"Ação Padrão"}
