function normalizeSave(save,legacyTarget=""){const x=save&&typeof save==="object"?save:{},legacySkill=x.skill||legacyTarget||"Vontade",skill=legacySkill==="Acrobacia"?"Reflexo":legacySkill;return {...x,enabled:Boolean(x.enabled||legacyTarget),skill,attribute:ATTRS.includes(x.attribute)?x.attribute:"",dcUsed:x.dcUsed??null,success:x.success||"",failure:x.failure||""}}
function normalizeOmComponents(list){return (Array.isArray(list)?list:[]).map(x=>({...x,id:x.id||uid("om"),component:OM_COMPONENTS.includes(x.component)?x.component:"Outro",grade:Object.hasOwn(OM_GRADES,x.grade)?x.grade:"N/A",note:x.note||""}))}
function normalizeSpell(x={}){const legacySustain=x.action==="Sustentação",saveTarget=x.saveTarget==="Acrobacia"?"Reflexo":x.saveTarget||"";return {...x,id:x.id||uid("spell"),name:x.name||"Nova magia",cycle:MAGIC_CYCLES.includes(x.cycle)?x.cycle:"1º Ciclo",type:x.type==="Ataque"?"Técnica":(ABILITY_TYPES.includes(x.type)?x.type:"Técnica"),magicNature:MAGIC_NATURES.includes(x.magicNature)?x.magicNature:"Arcana",strength:MAGIC_STRENGTHS.includes(x.strength)?x.strength:"Fraca",function:MAGIC_FUNCTIONS.includes(x.function)?x.function:"Outro",originStatus:MAGIC_ORIGINS.includes(x.originStatus)?x.originStatus:"Legado",action:normalizeAction(x.action),range:x.range||"",targets:x.targets||"",area:x.area||"",duration:num(x.duration),durationUnit:DURATION_UNITS.includes(x.durationUnit)?x.durationUnit:(x.durationUnit||"Rodadas"),manaCostOverride:x.manaCostOverride??null,additionalCost:x.additionalCost||"",omExtra:num(x.omExtra),omComponents:normalizeOmComponents(x.omComponents),complexity:Object.hasOwn(COMPLEXITY_MODIFIERS,x.complexity)?x.complexity:"Moderada",restrictions:x.restrictions||"",mechanicalEffect:x.mechanicalEffect||"",notes:x.notes||"",saveTarget,save:normalizeSave(x.save,saveTarget),transcribed:Boolean(x.transcribed),transcriptionPrepared:Boolean(x.transcriptionPrepared||x.transcribed),recitation:{allowed:Boolean(x.recitation?.allowed),target:x.recitation?.target||"Dano",multiplier:1.5},nativeReaction:Boolean(x.nativeReaction||x.action==="Reação"||x.type==="Reação"),reactionCompleteOverride:Boolean(x.reactionCompleteOverride),removesDying:Boolean(x.removesDying),masterAuthorized:Boolean(x.masterAuthorized),sustain:{enabled:Boolean(x.sustain?.enabled||legacySustain||x.durationUnit==="Sustentada"),allowsActions:Boolean(x.sustain?.allowsActions),bypassCheck:Boolean(x.sustain?.bypassCheck),extraOm:x.sustain?.extraOm===undefined?3:num(x.sustain.extraOm)},attack:normalizeAttack(x.attack)}}
function normalizeTrick(x={}){return {...x,id:x.id||uid("trick"),name:x.name||"Novo truque",manaCost:x.manaCost===undefined?0:Math.max(0,num(x.manaCost)),action:normalizeAction(x.action),description:x.description||"",mechanicalEffect:x.mechanicalEffect||"",notes:x.notes||"",attack:normalizeAttack(x.attack)}}
function criticalMargin(attack){const margin=Number(attack?.criticalMargin);return Number.isFinite(margin)&&margin>=1&&margin<=20?Math.floor(margin):20}
function criticalRange(attack){const margin=criticalMargin(attack);return margin>=20?"20":`${margin}–20`}
function options(list,current){return list.map(x=>`<option ${x===current?"selected":""}>${esc(x)}</option>`).join("")}
function mappedOptions(map,current){return Object.entries(map).map(([value,label])=>`<option value="${esc(value)}" ${value===current?"selected":""}>${esc(label)}</option>`).join("")}
function attrOptions(current){return ATTRS.map(a=>`<option value="${a}" ${a===current?"selected":""}>${ATTR_LABEL[a]}</option>`).join("")}
function toast(msg,error=false){const el=document.createElement("div");el.className=`toast ${error?"error":""}`;el.textContent=msg;document.getElementById("toastRegion").append(el);setTimeout(()=>el.remove(),3200)}
function normalizeStatusBonuses(list){return (Array.isArray(list)?list:[]).map(x=>({...x,target:x.target==="DP"?"DT":x.target,value:num(x.value)})).filter(x=>STATUS_TARGETS.includes(x.target))}
function normalizeResistances(list){return (Array.isArray(list)?list:[]).map(x=>({id:x.id||uid("resistance"),type:RESISTANCE_TYPES.includes(x.type)?x.type:"Físico",value:num(x.value)}))}
