function normalizeHybridRaces(list){const valid=["Humano","Receptáculo","Dragão","Golem","Vampiro","Corrupto","Celestial","Abissal"],unique=[];(Array.isArray(list)?list:[]).forEach(r=>{if(valid.includes(r)&&!unique.includes(r)&&unique.length<3)unique.push(r)});for(const fallback of ["Humano","Receptáculo"])if(unique.length<2&&!unique.includes(fallback))unique.push(fallback);return unique.slice(0,3)}
function patamarFor(existence){return EXISTENCE[LEGACY_PATAMAR[existence]||existence]||PATAMARES[0]}
function uniqueLevelOptions(existence){return [...patamarFor(existence).uniqueLevels]}
function abilityLevelRank(level){return Math.max(0,ABILITY_LEVELS.indexOf(level))}
function uniqueAbilityLevelFor(source){const unique=(source.abilities||[]).find(x=>(x.origins||[]).includes("Única"));return unique?.level||uniqueLevelOptions(source.identity.existence)[0]}
function abilityLevelWarning(source,ability){if((ability.origins||[]).includes("Única"))return !uniqueLevelOptions(source.identity.existence).includes(ability.level)?`Nível fora da progressão de ${source.identity.existence}.`:"";return abilityLevelRank(ability.level)>abilityLevelRank(uniqueAbilityLevelFor(source))?`Acima da Habilidade Única (${uniqueAbilityLevelFor(source)}). Exceção narrativa permitida.`:""}
function ensureProgressionState(source,migrating=false){const idx=tierIndex(source.identity.existence),existing=source.progression&&typeof source.progression==="object"?source.progression:{},classChanged=existing.className&&existing.className!==source.identity.className,p={className:source.identity.className,currentTier:idx,hpSnapshots:Array.isArray(existing.hpSnapshots)?existing.hpSnapshots.map(num):[],manaSnapshots:Array.isArray(existing.manaSnapshots)?existing.manaSnapshots.map(num):[],inferred:Boolean(existing.inferred),migrationNote:existing.migrationNote||""};if(classChanged){p.hpSnapshots=[];p.manaSnapshots=[];p.inferred=true;p.migrationNote="Classe alterada: histórico anterior foi inferido com os atributos disponíveis."}const attrs=effectiveAttributesFor(source);for(let i=0;i<idx;i++){if(p.hpSnapshots[i]===undefined)p.hpSnapshots[i]=num(attrs.constituicao);if(source.identity.className==="Arcanista"&&p.manaSnapshots[i]===undefined)p.manaSnapshots[i]=num(attrs.arcanismo)}if((migrating||!existing.className)&&idx>0){p.inferred=true;if(!p.migrationNote)p.migrationNote="Ficha antiga: snapshots anteriores inferidos com os atributos disponíveis na migração."}p.currentTier=idx;source.progression=p;return p}
function applyPatamarChange(source,nextExistence){const normalized=LEGACY_PATAMAR[nextExistence]||nextExistence;if(!EXISTENCE[normalized])return false;const oldIndex=tierIndex(source.identity.existence),nextIndex=tierIndex(normalized),p=ensureProgressionState(source),attrs=effectiveAttributesFor(source);if(nextIndex>oldIndex)for(let i=oldIndex;i<nextIndex;i++){if(p.hpSnapshots[i]===undefined)p.hpSnapshots[i]=num(attrs.constituicao);if(source.identity.className==="Arcanista"&&p.manaSnapshots[i]===undefined)p.manaSnapshots[i]=num(attrs.arcanismo)}source.identity.existence=normalized;p.currentTier=nextIndex;return true}

function racialBonusSpec(race){const specs={
  Humano:{abilityId:"race-Humano-versatile",max:1,defaults:c=>[{attribute:c.primary||"forca",value:2}]},
  "Receptáculo":{abilityId:"race-Receptáculo-versatile",max:1,defaults:c=>[{attribute:c.primary||"forca",value:2}]},
  "Dragão":{abilityId:"race-dragon-scales",max:2,defaults:()=>[{attribute:"constituicao",value:2},{attribute:"destreza",value:2}]},
  Golem:{abilityId:"race-golem-adaptation",max:1,defaults:c=>[{attribute:c.primary||"forca",value:5}]},
  Vampiro:{abilityId:"race-vamp-minor",max:2,defaults:c=>[{attribute:c.primary||"forca",value:2},{attribute:c.secondary||"destreza",value:2}]},
  Abissal:{abilityId:"race-abyssal-being",max:2,defaults:c=>[{attribute:c.primary||"forca",value:2},{attribute:c.secondary||"destreza",value:2}]}
};return specs[race]||null}
