function renderCombatTrauma(d){const value=state.combatState.traumaCurrent;return `<div class="combat-trauma"><div><span>Trauma</span><strong>${value} / ${d.traumaMax}</strong></div><div class="resource-stepper trauma-stepper"><button data-action="adjust-combat-resource" data-resource-kind="trauma" data-resource-field="current" data-delta="-1" aria-label="Diminuir Trauma">−</button><input type="number" min="0" max="${d.traumaMax}" value="${value}" data-combat-resource-input="trauma" data-resource-field="current" aria-label="Trauma atual"><button data-action="adjust-combat-resource" data-resource-kind="trauma" data-resource-field="current" data-delta="1" aria-label="Aumentar Trauma">+</button></div></div>`}
function renderActionEconomy(){const c=state.combatState,labels={standard:"Padrão",movement:"Movimento",free:"Livre",bonus:"Bônus",reaction:"Reação"};return `<div class="action-economy">${Object.entries(labels).map(([key,label])=>`<button class="action-token ${c.actions[key]?"available":"spent"}" data-action="toggle-action-token" data-key="${key}"><span>${label}</span><strong>${c.actions[key]?"Disponível":"Gasta"}</strong></button>`).join("")}</div><div class="section-tools action-guide-tools"><button class="btn danger" data-action="spend-complete-action">Marcar Ação Completa</button><button class="btn ghost" data-action="restore-actions">Restaurar todas</button></div><p class="hint">Guia manual: clique em cada ação para marcar ou desmarcar. A ficha não avança turnos nem rodadas automaticamente.</p>`}
