function renderCombat(){const d=derivedStatus(),a=effectiveAttributes(),attacks=getAttacks(),active=state.anomalies.filter(x=>x.active),activatables=[...state.abilities.filter(x=>x.type==="Ativa").map(x=>({kind:"abilities",...x})),...state.modifications.filter(x=>x.activatable).map(x=>({kind:"modifications",...x}))];syncCombatStateFor(state);return `<div class="hero"><div><h2>Modo Combate</h2><p>${esc(state.identity.name||"Personagem")} · estado atual preservado entre ficha e combate</p></div><button class="btn" data-roll-initiative>Rolar iniciativa</button></div><div class="combat-layout"><div class="grid">
${card("combat-status","Recursos de Combate",`<div class="combat-resources" aria-label="Recursos vitais">${renderCombatResource("hp",d.hpMax)}${renderCombatResource("mana",d.manaMax)}${renderCombatResource("sanity",d.sanityMax)}</div>${renderCombatTrauma(d)}<div class="stats combat-secondary-stats"><div class="stat"><label>CA</label><strong>${d.ac}</strong></div><div class="stat"><label>DT</label><strong>${d.dt}</strong></div><div class="stat"><label>Iniciativa</label><strong>${d.initiative>=0?"+":""}${d.initiative}</strong></div><div class="stat"><label>Deslocamento</label><strong>${d.movement}m</strong></div><div class="stat"><label>Proficiência</label><strong>+${proficiency()}</strong></div></div>`,"span-12")}
${card("combat-turn","Guia de Ações",renderActionEconomy(),"span-12")}
${card("combat-dying","Morrendo",renderDyingPanel(),"span-12")}
${card("combat-sustain","Sustentação",renderSustainPanel(),"span-12")}
${card("combat-attacks","Ataques / Ações",`<div class="combat-actions">${attacks.length?attacks.map(x=>{const m=attackModifierFor(state,x.attack,x.kind==="spells");return `<button class="roll-btn" data-open-action="${x.kind}" data-id="${x.id}"><strong>${esc(x.name)}</strong><small>${esc(x.attack.damage)} · ${x.attack.autoHit?"acerto automático":`teste ${m.total>=0?"+":""}${m.total}`}</small></button>`}).join(""):'<div class="empty">Nenhum ataque configurado.</div>'}${state.spells.filter(x=>!x.attack).map(x=>`<button class="roll-btn" data-open-action="spells" data-id="${x.id}"><strong>${esc(x.name)}</strong><small>${esc(x.cycle)} · ${spellCost(x)} Mana · ${esc(x.magicNature)}</small></button>`).join("")}${state.tricks.filter(x=>!x.attack).map(x=>`<button class="roll-btn" data-open-action="tricks" data-id="${x.id}"><strong>${esc(x.name)}</strong><small>Truque · ${x.manaCost} Mana · ${esc(x.action)}</small></button>`).join("")}</div>`,"span-12")}
${card("combat-active","Efeitos Ativáveis",activatables.length?`<div class="combat-actions">${activatables.map(x=>`<button class="roll-btn" data-action="toggle-source" data-kind="${x.kind}" data-id="${x.id}"><strong>${esc(x.name)}</strong><small>${x.enabled?"Ligada · clique para desligar":"Desligada · clique para ligar"}</small></button>`).join("")}</div>`:'<div class="empty">Nenhum efeito ativável.</div>',"span-12")}
${card("combat-skills","Perícias",`<p class="hint skill-rule-hint">Bônus-base sem atributo; escolha a inclusão antes da rolagem.</p><div class="combat-actions">${skillEntriesFor(state).map(({id,name})=>{const c=skillBonusFor(state,id,false);return `<button class="roll-btn" data-roll-skill="${esc(id)}"><strong>${esc(name)}</strong><small>1d20 ${c.baseBonus>=0?"+":""}${c.baseBonus} · ${ATTR_LABEL[c.attribute]} opcional</small></button>`}).join("")}</div>`,"span-12")}
${card("combat-anomalies","Anomalias Ativas",active.length?active.map(x=>`<div class="history-entry"><strong>${esc(x.name)}</strong><small>${(x.effects||[]).map(e=>`${effectTargetLabel(e.target)} ${effectNotation(e)}`).join(" · ")}</small></div>`).join(""):'<div class="empty">Nenhuma anomalia ativa.</div>',"span-12")}</div>
<aside>${state.latestResult?renderImmediateResult(state.latestResult,true):""}${card("dice","Dados",`<div class="dice-row">${[4,6,8,10,12,20,100].map(d=>`<button class="btn small" data-die="d${d}">d${d}</button>`).join("")}</div><div class="dice-expression"><input class="inline-input" id="diceExpression" placeholder="2d10 + 1d6 + 5"><button class="btn" data-roll-expression>Rolar</button></div>`,"span-12")}${card("history","Histórico",`<div class="section-tools"><button class="btn small danger" data-action="clear-history">Limpar</button></div><div class="history">${state.rollHistory.length?state.rollHistory.map(renderHistory).join(""):'<div class="empty">As rolagens aparecerão aqui.</div>'}</div>`,"span-12")}</aside></div>`}
function getAttacks(){const out=[];allAbilities().forEach(x=>{if(x.attack)out.push({kind:x.locked?"base": "abilities",...x})});state.spells.forEach(x=>{if(x.attack)out.push({kind:"spells",...x})});state.tricks.forEach(x=>{if(x.attack)out.push({kind:"tricks",...x})});state.inventory.equipment.forEach(x=>{if(x.attack)out.push({kind:"equipment",...x})});return out}
