function openSkillExecution(name){const c=skillBonusFor(state,name,false),label=skillLabelFor(state,name);pendingAction={kind:"skill",id:name};document.getElementById("executeContent").innerHTML=`<h2>Rolar perícia · ${esc(label)}</h2><div class="execution-summary skill-execution-summary"><p>Bônus-base: <strong>${c.baseBonus>=0?"+":""}${c.baseBonus}</strong><small>Proficiência ${c.proficiencyBonus>=0?"+":""}${c.proficiencyBonus} · Extra ${c.extraBonus>=0?"+":""}${c.extraBonus}</small></p><p>Atributo disponível: <strong>${ATTR_LABEL[c.attribute]} ${c.attributeBonus>=0?"+":""}${c.attributeBonus}</strong></p><p>Bônus final: <strong data-skill-final>${c.total>=0?"+":""}${c.total}</strong></p></div><div class="execution-options"><label><input id="executeSkillAttribute" type="checkbox"> Incluir bônus de ${ATTR_LABEL[c.attribute]}</label></div>`;document.getElementById("executeDialog").showModal();updateExecutionPreview()}
function executionOptions(){return {recite:Boolean(document.getElementById("executeRecite")?.checked),transcribed:Boolean(document.getElementById("executeTranscribed")?.checked),useAsReaction:Boolean(document.getElementById("executeAsReaction")?.checked),includeAttribute:Boolean(document.getElementById("executeSkillAttribute")?.checked)}}
