function attackModifierFor(source,attack,isSpell=false){const attrs=effectiveAttributesFor(source),attribute=isSpell?"arcanismo":(attack?.attribute||"forca"),attributeValue=num(attrs[attribute]),proficiencyBonus=proficiencyFor(source),additionalBonus=num(attack?.bonus);return {attribute,attributeValue,proficiencyBonus,additionalBonus,total:attributeValue+proficiencyBonus+additionalBonus}}
function attackHitOutcome(attack,attributeValue,natural){const margin=criticalMargin(attack),modifier=num(attributeValue)+num(attack?.bonus);if(attack?.autoHit)return {natural:null,modifier,total:null,critical:false,margin,autoHit:true};const die=clamp(Math.floor(num(natural)),1,20),total=die+modifier;return {natural:die,modifier,total,critical:Boolean(attack?.canCrit)&&die>=margin,margin,autoHit:false}}
