function executePending(){if(!pendingAction)return false;const opts=executionOptions();if(pendingAction.kind==="skill"){const name=pendingAction.id,label=skillLabelFor(state,name),c=skillBonusFor(state,name,opts.includeAttribute),roll=parseDice(`1d20${c.total>=0?"+":""}${c.total}`),total=applyPercent(roll.total,"Acertos"),effectSuffix=total!==roll.total?` · efeitos em Acertos: ${roll.total} → ${total}`:"",attributeText=opts.includeAttribute?`${ATTR_LABEL[c.attribute]} ${c.attributeBonus>=0?"+":""}${c.attributeBonus} incluído`:"atributo não incluído",result={label,total,detail:`${roll.detail} · bônus-base ${c.baseBonus>=0?"+":""}${c.baseBonus} · ${attributeText}${effectSuffix}`,kind:"skill",time:Date.now()};state.latestResult=result;state.rollHistory.push({id:uid("roll"),...result});if(state.rollHistory.length>100)state.rollHistory.shift();pendingAction=null;commit();return true}const item=findItem(pendingAction.kind,pendingAction.id),isSpell=pendingAction.kind==="spells",isTrick=pendingAction.kind==="tricks";if(!item)return false;const selectedAction=opts.useAsReaction?"Reação":(item.action||"Ação Padrão");let cost=isSpell?spellCost(item,{transcribed:opts.transcribed,recited:opts.recite,useAsReaction:opts.useAsReaction}):isTrick?Math.max(0,num(item.manaCost)):0,manaPlan=null;if(cost>0){manaPlan=manaSpendPlan(state.combatState.manaCurrent,state.combatState.manaTemporary,cost);if(!manaPlan.canPay){toast("Mana insuficiente para executar esta ação.",true);return false}state.combatState.manaCurrent=manaPlan.realCurrent;state.combatState.manaTemporary=manaPlan.temporaryCurrent}if(isSpell&&opts.transcribed){item.transcriptionPrepared=false;item.transcribed=false}let result={label:item.name,total:0,detail:`${selectedAction}${executionModeDetail(item,opts)} · Custo ${cost} Mana${manaPlan?` · temporária ${manaPlan.temporarySpent}, real ${manaPlan.realSpent}`:""}`,kind:"action",cost,time:Date.now()};if(item.attack){const attackBase=attackModifierFor(state,item.attack,isSpell),baseHit=attackHitOutcome(item.attack,attackBase.attributeValue+attackBase.proficiencyBonus,rollNatural(20)),hit={...baseHit};if(!hit.autoHit){hit.baseTotal=hit.total;hit.total=applyPercent(hit.total,"Acertos")}const criticalMultiplier=hit.critical?(item.attack.criticalMultiplier||2):1,damageRoll=parseDice(item.attack.damage,criticalMultiplier);damageRoll.total+=num(item.attack.bonus);damageRoll.detail+=` + bônus fixo ${num(item.attack.bonus)}`;if(opts.recite&&item.recitation?.target==="Dano"){damageRoll.total=SYSTEM_CONFIG.rounding(damageRoll.total*1.5);damageRoll.detail+=" · Recitação ×1,5"}const damageTotal=applyPercent(damageRoll.total,"Danos"),hitText=hit.autoHit?"Acerto automático":`Natural ${hit.natural} + modificadores ${hit.modifier>=0?"+":""}${hit.modifier} = ${hit.total}`;result={label:item.name,total:damageTotal,detail:`${hitText} · Dano ${damageTotal} · ${selectedAction}${executionModeDetail(item,opts)}${manaPlan?` · temporária ${manaPlan.temporarySpent}, real ${manaPlan.realSpent}`:""}`,kind:"attack",cost,time:Date.now(),attack:hit,damage:{total:damageTotal,baseTotal:damageRoll.total,detail:damageRoll.detail,type:item.attack.damageType||"",expression:item.attack.damage}}}else if(opts.recite&&item.duration){result.total=SYSTEM_CONFIG.rounding(num(item.duration)*1.5);result.detail=`Duração recitada: ${result.total} ${item.durationUnit}${manaPlan?` · temporária ${manaPlan.temporarySpent}, real ${manaPlan.realSpent}`:""}`}state.latestResult=result;state.rollHistory.push({id:uid("roll"),...result});if(state.rollHistory.length>100)state.rollHistory.shift();pendingAction=null;commit();return true}

function renderImmediateResult(result,compact=false){if(result.kind!=="attack"||!result.attack||!result.damage)return `<div class="result-highlight"><small>ÚLTIMO RESULTADO</small><strong>${esc(result.label)} · ${result.total}</strong><span>${esc(result.detail)}</span></div>`;const hit=result.attack,damage=result.damage;return `<div class="result-highlight attack-result ${hit.critical?"is-critical":""}"><small>${compact?"ÚLTIMO RESULTADO":"ATAQUE"} — ${esc(result.label)}</small><div class="result-stages"><section><span>ACERTO</span>${hit.autoHit?'<strong>Automático</strong>':`<div class="result-numbers"><div><small>NATURAL</small><strong>${hit.natural}</strong></div><div><small>MODIFICADORES</small><strong>${hit.modifier>=0?"+":""}${hit.modifier}</strong></div><div><small>TOTAL</small><strong>${hit.total}</strong></div></div>`}${hit.critical?`<div class="critical-banner">CRÍTICO! <small>margem ${hit.margin}–20</small></div>`:""}</section><section><span>DANO</span><strong class="damage-total">${damage.total}</strong><small>${esc(damage.detail)}${damage.type?` · ${esc(damage.type)}`:""}</small></section></div></div>`}
function showResultDialog(result){const dialog=document.getElementById("resultDialog"),content=document.getElementById("resultContent");if(!dialog||!content)return;content.innerHTML=renderImmediateResult(result);if(dialog.open)dialog.close();dialog.showModal()}

function criticalDamageExpression(expression,multiplier=2){const mult=Math.max(1,Math.floor(num(multiplier))||1);return String(expression).replace(/(\d*)d(\d+)/gi,(_,count,sides)=>`${(Number(count)||1)*mult}d${sides}`)}
function parseDice(expression,critical=false){const multiplier=critical===true?2:critical===false?1:Math.max(1,Math.floor(num(critical))||1),clean=String(expression).replace(/\s+/g,"").toLowerCase();if(!clean||!/^[+\-]?(?:\d*d\d+|\d+)(?:[+\-](?:\d*d\d+|\d+))*$/.test(clean))throw new Error("Expressão de dados inválida.");const tokens=clean.match(/[+\-]?[^+\-]+/g);let total=0;const details=[];for(const token of tokens){const sign=token.startsWith("-")?-1:1,body=token.replace(/^[+\-]/,"");if(body.includes("d")){let [count,sides]=body.split("d").map(Number);count=(count||1)*multiplier;if(count>1000||sides<1||sides>1000000)throw new Error("Limites de dados excedidos.");const rolls=Array.from({length:count},()=>Math.floor(Math.random()*sides)+1);total+=sign*rolls.reduce((a,b)=>a+b,0);details.push(`${sign<0?"- ":""}${count}d${sides} [${rolls.join(", ")}]`)}else{total+=sign*Number(body);details.push(`${sign<0?"- ":"+ "}${body}`)}}return {total,detail:details.join(" ")}}
function applyPercent(value,target){return calculateEffectValue(state,target,value)}
function addHistory(label,result,target){const total=target?applyPercent(result.total,target):result.total,suffix=total!==result.total?` → ${target} ${activeEffects()[target]>=0?"+":""}${activeEffects()[target]}% = ${total}`:"",entry={id:uid("roll"),label,total,detail:result.detail+suffix,kind:"roll",time:Date.now()};state.latestResult=entry;state.rollHistory.push(entry);if(state.rollHistory.length>100)state.rollHistory.shift();commit();setTimeout(()=>showResultDialog(entry),0);return total}

function loadPhotoImage(source){return new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>resolve(image);image.onerror=()=>reject(new Error("Não foi possível processar esta imagem."));image.src=source})}
function readPhotoFile(file){return new Promise((resolve,reject)=>{if(!file||!/^image\/(?:jpeg|png|webp)$/i.test(file.type||""))return reject(new Error("Escolha uma imagem JPG, PNG ou WebP."));if(file.size>20*1024*1024)return reject(new Error("A imagem deve ter no máximo 20 MB."));const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error("Não foi possível ler esta imagem."));reader.readAsDataURL(file)})}
async function preparePhotoSource(file){const original=await readPhotoFile(file),image=await loadPhotoImage(original),longest=Math.max(image.naturalWidth,image.naturalHeight),scale=Math.min(1,1600/longest),width=Math.max(1,Math.round(image.naturalWidth*scale)),height=Math.max(1,Math.round(image.naturalHeight*scale)),canvas=document.createElement("canvas");canvas.width=width;canvas.height=height;const context=canvas.getContext("2d",{alpha:false});context.fillStyle="#d4bd98";context.fillRect(0,0,width,height);context.drawImage(image,0,0,width,height);return canvas.toDataURL("image/jpeg",.86)}
let cropSession=null;
function cropViewportMetrics(){const viewport=document.getElementById("cropViewport"),rect=viewport.getBoundingClientRect();return {viewport,width:rect.width,height:rect.height}}
function clampCropOffsets(){if(!cropSession)return;const {width,height}=cropViewportMetrics(),displayWidth=cropSession.image.naturalWidth*cropSession.baseScale*cropSession.zoom,displayHeight=cropSession.image.naturalHeight*cropSession.baseScale*cropSession.zoom,maxX=Math.max(0,(displayWidth-width)/2),maxY=Math.max(0,(displayHeight-height)/2);cropSession.offsetX=clamp(cropSession.offsetX,-maxX,maxX);cropSession.offsetY=clamp(cropSession.offsetY,-maxY,maxY)}
function updateCropPreview(){if(!cropSession)return;clampCropOffsets();const imageEl=document.getElementById("cropImage"),scale=cropSession.baseScale*cropSession.zoom;imageEl.style.width=`${cropSession.image.naturalWidth*scale}px`;imageEl.style.height=`${cropSession.image.naturalHeight*scale}px`;imageEl.style.left=`calc(50% + ${cropSession.offsetX}px)`;imageEl.style.top=`calc(50% + ${cropSession.offsetY}px)`;document.getElementById("cropZoom").value=cropSession.zoom}
function currentCropRect(){const {width,height}=cropViewportMetrics(),scale=cropSession.baseScale*cropSession.zoom,displayWidth=cropSession.image.naturalWidth*scale,displayHeight=cropSession.image.naturalHeight*scale,left=width/2+cropSession.offsetX-displayWidth/2,top=height/2+cropSession.offsetY-displayHeight/2,sx=clamp(-left/scale,0,cropSession.image.naturalWidth),sy=clamp(-top/scale,0,cropSession.image.naturalHeight),sw=Math.min(width/scale,cropSession.image.naturalWidth-sx),sh=Math.min(height/scale,cropSession.image.naturalHeight-sy);return {sx,sy,sw,sh}}
async function openCropEditor(sourceDataUrl,savedCrop=null){const image=await loadPhotoImage(sourceDataUrl),dialog=document.getElementById("cropDialog"),imageEl=document.getElementById("cropImage");imageEl.src=sourceDataUrl;if(!dialog.open)dialog.showModal();await new Promise(resolve=>requestAnimationFrame(resolve));const {width,height}=cropViewportMetrics(),baseScale=Math.max(width/image.naturalWidth,height/image.naturalHeight);cropSession={sourceDataUrl,image,baseScale,zoom:1,offsetX:0,offsetY:0,dragging:false,pointerId:null,lastX:0,lastY:0};if(savedCrop&&savedCrop.sw>0&&savedCrop.sh>0){const sourceScale=width/(savedCrop.sw*image.naturalWidth);cropSession.zoom=clamp(sourceScale/baseScale,1,3);const scale=baseScale*cropSession.zoom,displayWidth=image.naturalWidth*scale,displayHeight=image.naturalHeight*scale;cropSession.offsetX=-savedCrop.sx*image.naturalWidth*scale-width/2+displayWidth/2;cropSession.offsetY=-savedCrop.sy*image.naturalHeight*scale-height/2+displayHeight/2}updateCropPreview()}
function applyPhotoCrop(){if(!cropSession)return;const crop=currentCropRect(),canvas=document.createElement("canvas"),targetWidth=600,targetHeight=750;canvas.width=targetWidth;canvas.height=targetHeight;const context=canvas.getContext("2d",{alpha:false});context.fillStyle="#d4bd98";context.fillRect(0,0,targetWidth,targetHeight);context.drawImage(cropSession.image,crop.sx,crop.sy,crop.sw,crop.sh,0,0,targetWidth,targetHeight);state.identity.photoDataUrl=canvas.toDataURL("image/jpeg",.86);state.identity.photoSourceDataUrl=cropSession.sourceDataUrl;state.identity.photoCrop={sx:crop.sx/cropSession.image.naturalWidth,sy:crop.sy/cropSession.image.naturalHeight,sw:crop.sw/cropSession.image.naturalWidth,sh:crop.sh/cropSession.image.naturalHeight};cropSession=null;document.getElementById("cropDialog").close();commit();toast("Foto recortada e salva.")}

function findItem(kind,id){if(kind==="equipment")return state.inventory.equipment.find(x=>x.id===id);if(kind==="base")return allAbilities().find(x=>x.id===id);return (state[kind]||[]).find(x=>x.id===id)}
function setPath(path,value){const p=path.split(".");if(p[0]==="racialBonus"){const bonuses=ensureRacialAbilityBonuses(p[1]),entry=bonuses[num(p[2])];if(entry)entry[p[3]]=value;return}if(p[0]==="item"){const item=findItem(p[1],p[2]);if(!item||item.locked)return;setNested(item,p.slice(3),value);return}if(p[0]==="effect"){const an=state.anomalies.find(x=>x.id===p[1]);const ef=an?.effects.find(x=>x.id===p[2]);if(ef)ef[p[3]]=value;return}setNested(state,p,value)}
function setNested(obj,parts,value){for(let i=0;i<parts.length-1;i++){if(!obj[parts[i]])obj[parts[i]]={};obj=obj[parts[i]]}obj[parts.at(-1)]=value}
function readInput(el){if(el.type==="checkbox")return el.checked;if(el.type==="number")return num(el.value);return el.value}
function setCombatResourceValue(kind,field,value){const d=derivedStatus(),numeric=num(value);if(kind==="trauma"){state.combatState.traumaCurrent=clamp(numeric,0,d.traumaMax);return state.combatState.traumaCurrent}const key=`${kind}${field==="temporary"?"Temporary":"Current"}`;if(field==="temporary")state.combatState[key]=Math.max(0,numeric);else state.combatState[key]=clamp(numeric,0,combatResourceMaximum(kind,d));return state.combatState[key]}
function updateCombatResourceVisual(kind){const d=derivedStatus();if(kind==="trauma"){const box=document.querySelector(".combat-trauma");if(box)box.querySelector("strong").textContent=`${state.combatState.traumaCurrent} / ${d.traumaMax}`;return}const box=document.querySelector(`[data-resource="${kind}"]`);if(!box)return;const meta=COMBAT_RESOURCE_META[kind],maximum=combatResourceMaximum(kind,d),current=state.combatState[`${kind}Current`],temporary=state.combatState[`${kind}Temporary`],track=box.querySelector(".combat-resource-track");box.querySelector(".combat-resource-head b").textContent=`${current} / ${maximum}`;box.querySelector(".combat-resource-head em").textContent=`+${temporary} Temp.`;box.querySelector(".combat-resource-track i").style.setProperty("--resource-pct",`${resourcePercent(current,maximum)}%`);box.querySelector(".combat-resource-temporary").style.setProperty("--temporary-pct",`${resourcePercent(temporary,maximum)}%`);track.setAttribute("aria-label",`${meta.label}: ${current} de ${maximum}; ${temporary} temporária`);track.setAttribute("aria-valuemax",maximum);track.setAttribute("aria-valuenow",clamp(current,0,maximum));track.setAttribute("aria-valuetext",`${current} de ${maximum}, mais ${temporary} temporária`)}

function bindDynamic(){document.querySelectorAll("[data-path]").forEach(el=>{if(el.tagName!=="SELECT"&&el.type!=="checkbox")el.addEventListener("input",()=>{if(el.type==="number"&&el.value==="")return;setPath(el.dataset.path,readInput(el));save()});el.addEventListener("change",()=>{const path=el.dataset.path;let value=readInput(el);
  if(path.startsWith("attributes."))value=clamp(value,0,constructionLimit());
  if(path.endsWith(".attack.criticalMargin"))value=clamp(Math.floor(num(value)),1,20);
  if(path.endsWith(".attack.criticalMultiplier"))value=Math.max(1,Math.floor(num(value))||1);
  if(path==="racialConfig.corruption")value=clamp(value,1,100);
  if(path==="racialConfig.secondary"&&["Vampiro","Abissal"].includes(state.identity.race)&&value===state.racialConfig.primary){el.value=state.racialConfig.secondary;toast("Os dois atributos raciais devem ser diferentes.",true);return}
  if(path==="racialConfig.primary"&&["Vampiro","Abissal"].includes(state.identity.race)&&value===state.racialConfig.secondary){el.value=state.racialConfig.primary;toast("Os dois atributos raciais devem ser diferentes.",true);return}
  if(path.startsWith("item.spells.")&&path.endsWith(".saveTarget")){setPath(path,value);const spell=findItem("spells",path.split(".")[2]);spell.save=normalizeSave({...spell.save,enabled:Boolean(value),skill:value||spell.save?.skill},value);commit();return}
  if(path==="identity.existence"){applyPatamarChange(state,value);ATTRS.forEach(a=>state.attributes[a]=clamp(state.attributes[a],0,constructionLimit()));commit();return}
  if(path.startsWith("racialConfig.hybridRaces.")){setPath(path,value);state.racialConfig.hybridRaces=normalizeHybridRaces(state.racialConfig.hybridRaces);commit();return}
  if(path==="identity.race"||path==="identity.className")toast(`${path.endsWith("race")?"Raça":"Classe"} alterada; conteúdo manual preservado.`);setPath(path,value);if(path==="identity.className")ensureProgressionState(state,true);commit()})});
document.querySelectorAll("[data-skill]").forEach(el=>{if(el.type==="number")el.addEventListener("input",()=>{skillRecordFor(state,el.dataset.skill)[el.dataset.key]=readInput(el);save()});el.addEventListener("change",()=>{const s=skillRecordFor(state,el.dataset.skill),key=el.dataset.key,val=readInput(el);if(key==="proficient"&&val&&!s.proficient&&proficientSkillCount(state)>=proficiencyLimit()){el.checked=false;toast("Limite de perícias proficientes atingido.",true);return}s[key]=val;commit()})});
document.querySelectorAll("[data-origin-kind]").forEach(el=>el.addEventListener("change",()=>{const x=findItem(el.dataset.originKind,el.dataset.id);if(!x)return;x.origins=x.origins||[];if(el.checked&&!x.origins.includes(el.value))x.origins.push(el.value);if(!el.checked)x.origins=x.origins.filter(o=>o!==el.value);commit()}));
document.querySelectorAll("[data-unlocked-cycle]").forEach(el=>el.addEventListener("change",()=>{const cycle=el.dataset.unlockedCycle,list=state.magicProgression.unlockedCycles;if(el.checked&&!list.includes(cycle))list.push(cycle);if(!el.checked)state.magicProgression.unlockedCycles=list.filter(x=>x!==cycle);state.magicProgression.unlockedCycles.sort((a,b)=>MAGIC_CYCLES.indexOf(a)-MAGIC_CYCLES.indexOf(b));commit()}));
document.querySelectorAll("[data-combat-resource-input]").forEach(el=>{el.addEventListener("input",()=>{if(el.value==="")return;const kind=el.dataset.combatResourceInput,field=el.dataset.resourceField,value=setCombatResourceValue(kind,field,el.value);el.value=value;updateCombatResourceVisual(kind);save()});el.addEventListener("change",()=>{const kind=el.dataset.combatResourceInput;setCombatResourceValue(kind,el.dataset.resourceField,el.value);commit()})});
}

document.addEventListener("click",e=>{const b=e.target.closest("button");if(!b)return;const act=b.dataset.action;
  if(b.dataset.openAction){openExecution(b.dataset.openAction,b.dataset.id);return}
  if(b.dataset.mode){state.mode=b.dataset.mode;commit();return}
  if(act==="toggle-action-token"){state.combatState.actions[b.dataset.key]=!state.combatState.actions[b.dataset.key];commit();return}
  if(act==="spend-complete-action"){spendAction(state,"Ação Completa");commit();return}
  if(act==="restore-actions"){state.combatState.actions=freshActions();commit();return}
  if(act==="toggle-dying"){setDyingManual(state,!state.combatState.dying);commit();return}
  if(act==="toggle-death-marker"){const marker=clamp(Math.floor(num(b.dataset.marker)),1,3),current=state.combatState.deathMarkers;setDeathMarkersManual(state,marker<=current?marker-1:marker);commit();return}
  if(act==="toggle-sustain"){const id=b.dataset.id;state.combatState.sustain={...state.combatState.sustain,spellId:state.combatState.sustain.spellId===id?"":id};commit();return}
  if(act==="stop-sustain"){state.combatState.sustain={spellId:"",allowActions:false,ignoreConcentration:false,dc:0};commit();return}
  if(act==="adjust-combat-resource"){const kind=b.dataset.resourceKind,field=b.dataset.resourceField,key=kind==="trauma"?"traumaCurrent":`${kind}${field==="temporary"?"Temporary":"Current"}`,next=num(state.combatState[key])+num(b.dataset.delta);setCombatResourceValue(kind,field,next);commit();return}
  if(act==="choose-photo"){document.getElementById("characterPhotoFile").click();return}
  if(act==="edit-photo"){openCropEditor(state.identity.photoSourceDataUrl||state.identity.photoDataUrl,state.identity.photoCrop).catch(err=>toast(err.message,true));return}
  if(act==="remove-photo"){state.identity.photoDataUrl="";state.identity.photoSourceDataUrl="";state.identity.photoCrop=null;commit();toast("Foto removida da ficha.");return}
  if(act==="toggle-edit"){state.ui.editing[b.dataset.section]=!state.ui.editing[b.dataset.section];commit();return}
  if(act==="toggle-item-edit"){const key=itemEditKey(b.dataset.kind,b.dataset.id),item=findItem(b.dataset.kind,b.dataset.id);if(item?.configurableAttributeBonuses)ensureRacialAbilityBonuses(item.id);state.ui.editingItems[key]=!state.ui.editingItems[key];commit();return}
  if(act==="toggle-card"){state.collapsed[b.dataset.id]=!state.collapsed[b.dataset.id];commit();return}
  if(act==="toggle-item"){state.itemCollapsed[b.dataset.id]=!state.itemCollapsed[b.dataset.id];commit();return}
  if(act==="add"){const k=b.dataset.kind;let item=null;if(k==="abilities"){item=newAbility();state.abilities.push(item)}if(k==="spells"){if(!knownMagicStatus(state).canAdd){toast("Limite de magias conhecidas atingido. Aumente o PA antes de adicionar.",true);return}item=newSpell();state.spells.push(item)}if(k==="tricks"){item=newTrick();state.tricks.push(item)}if(k==="anomalies"){item=newAnomaly();state.anomalies.push(item)}if(k==="modifications"){item=newModification();state.modifications.push(item)}if(k==="equipment"){item=newEquipment();state.inventory.equipment.push(item)}if(item)state.ui.editingItems[itemEditKey(k,item.id)]=true;commit();return}
  if(act==="delete"){const k=b.dataset.kind;if(k==="equipment")state.inventory.equipment=state.inventory.equipment.filter(x=>x.id!==b.dataset.id);else state[k]=state[k].filter(x=>x.id!==b.dataset.id);delete state.ui.editingItems[itemEditKey(k,b.dataset.id)];commit();return}
  if(act==="enable-uses"){findItem(b.dataset.kind,b.dataset.id).uses={current:1,max:1,every:1,type:"Cena"};commit();return}
  if(act==="enable-attack"){findItem(b.dataset.kind,b.dataset.id).attack={damage:"1d6",attribute:"forca",bonus:0,damageType:"Físico",autoHit:false,canCrit:true,criticalMargin:20,criticalMultiplier:2};commit();return}
  if(act==="toggle-source"){const x=findItem(b.dataset.kind,b.dataset.id);if(x){x.enabled=!x.enabled;commit()}return}
  if(act==="add-attribute-bonus"){const x=findItem(b.dataset.kind,b.dataset.id);if(x){x.attributeBonuses=x.attributeBonuses||[];x.attributeBonuses.push({id:uid("attribute"),attribute:"forca",value:0});commit()}return}
  if(act==="delete-attribute-bonus"){const x=findItem(b.dataset.kind,b.dataset.id);if(x){x.attributeBonuses.splice(num(b.dataset.index),1);commit()}return}
  if(act==="add-status-bonus"){const x=findItem(b.dataset.kind,b.dataset.id);if(x){x.statusBonuses=x.statusBonuses||[];x.statusBonuses.push({id:uid("status"),target:"Vida",value:0});commit()}return}
  if(act==="delete-status-bonus"){const x=findItem(b.dataset.kind,b.dataset.id);if(x){x.statusBonuses.splice(num(b.dataset.index),1);commit()}return}
  if(act==="add-resistance"){const x=findItem(b.dataset.kind,b.dataset.id);if(x){x.resistances=x.resistances||[];x.resistances.push({id:uid("resistance"),type:"Arcana",value:0});commit()}return}
  if(act==="delete-resistance"){const x=findItem(b.dataset.kind,b.dataset.id);if(x){x.resistances.splice(num(b.dataset.index),1);commit()}return}
  if(act==="add-immunity"){const x=findItem(b.dataset.kind,b.dataset.id);if(x){x.immunities=x.immunities||[];x.immunities.push({id:uid("immunity"),type:"Fogo"});commit()}return}
  if(act==="delete-immunity"){const x=findItem(b.dataset.kind,b.dataset.id);if(x){x.immunities.splice(num(b.dataset.index),1);commit()}return}
  if(act==="add-racial-attribute-bonus"){const bonuses=ensureRacialAbilityBonuses(b.dataset.id),spec=racialBonusSpecByAbility(b.dataset.id);if(bonuses.length<(spec?.max||0)){bonuses.push({id:uid("racial-attribute"),attribute:"forca",value:0});commit()}return}
  if(act==="delete-racial-attribute-bonus"){const bonuses=ensureRacialAbilityBonuses(b.dataset.id);bonuses.splice(num(b.dataset.index),1);commit();return}
  if(act==="add-effect"){state.anomalies.find(x=>x.id===b.dataset.id).effects.push({id:uid("effect"),target:"Vida",mode:"fixed",value:0});commit();return}
  if(act==="toggle-anomaly"){const x=state.anomalies.find(x=>x.id===b.dataset.id);if(x){x.active=!x.active;commit()}return}
  if(act==="toggle-transcription"){const x=state.spells.find(x=>x.id===b.dataset.id);if(x){x.transcriptionPrepared=!x.transcriptionPrepared;x.transcribed=x.transcriptionPrepared;commit()}return}
  if(act==="delete-effect"){const x=state.anomalies.find(x=>x.id===b.dataset.id);x.effects=x.effects.filter(e=>e.id!==b.dataset.effect);commit();return}
  if(act==="clear-history"){state.rollHistory=[];commit();return}
  if(b.dataset.rollSkill){rollSkill(b.dataset.rollSkill);return} if(b.dataset.die){try{addHistory(b.dataset.die,parseDice(b.dataset.die))}catch(err){toast(err.message,true)}return}
  if(b.hasAttribute("data-roll-expression")){try{addHistory(document.getElementById("diceExpression").value,parseDice(document.getElementById("diceExpression").value))}catch(err){toast(err.message,true)}return}
  if(b.hasAttribute("data-roll-initiative")){const initiative=derivedStatus().initiative;addHistory("Iniciativa",parseDice(`1d20${initiative>=0?"+":""}${initiative}`),"Acertos");return}
  if(b.dataset.attackId){rollAttack(b.dataset.attackKind,b.dataset.attackId,b.dataset.critical==="true")}
});
function rollSkill(name){openSkillExecution(name)}
function rollAttack(kind,id){const x=findItem(kind,id);if(!x?.attack)return toast("Ataque não encontrado.",true);pendingAction={kind,id};try{if(executePending())setTimeout(()=>showResultDialog(state.latestResult),0)}catch(err){toast(err.message,true)}}

document.querySelectorAll(".tab").forEach(b=>b.addEventListener("click",()=>{state.mode=b.dataset.mode;commit()}));
document.getElementById("exportBtn").addEventListener("click",()=>{const blob=new Blob([JSON.stringify(state,null,2)],{type:"application/json"}),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download=`nightmare-${(state.identity.name||"ficha").toLowerCase().replace(/[^a-z0-9]+/g,"-")}.json`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast("Ficha exportada.")});
document.getElementById("importBtn").addEventListener("click",()=>document.getElementById("importFile").click());
document.getElementById("importFile").addEventListener("change",async e=>{try{const obj=JSON.parse(await e.target.files[0].text());if(!obj||typeof obj!=="object"||!obj.identity)throw new Error("JSON não parece ser uma ficha NIGHTMARE.");state=hydrate(obj);commit();toast("Ficha importada com sucesso.")}catch(err){toast(err.message,true)}finally{e.target.value=""}});
document.getElementById("characterPhotoFile").addEventListener("change",async e=>{const file=e.target.files?.[0];if(!file)return;document.getElementById("saveStatus").textContent="Preparando foto…";try{const source=await preparePhotoSource(file);document.getElementById("saveStatus").textContent="Salvo";await openCropEditor(source)}catch(err){document.getElementById("saveStatus").textContent="Salvo";toast(err.message,true)}finally{e.target.value=""}});
document.getElementById("resetBtn").addEventListener("click",()=>{const d=document.getElementById("confirmDialog");document.getElementById("dialogText").textContent="Isso apagará a ficha local atual. Exporte antes se quiser preservar os dados.";d.showModal();d.addEventListener("close",()=>{if(d.returnValue==="confirm"){state=defaultState();localStorage.removeItem(STORAGE_KEY);commit();toast("Ficha resetada.")}}, {once:true})});
document.getElementById("executeDialog").addEventListener("change",updateExecutionPreview);
document.getElementById("confirmExecute").addEventListener("click",e=>{e.preventDefault();try{if(executePending()){document.getElementById("executeDialog").close();setTimeout(()=>showResultDialog(state.latestResult),0)}}catch(err){toast(err.message,true)}});
document.getElementById("cropZoom").addEventListener("input",e=>{if(!cropSession)return;const previous=cropSession.zoom,next=clamp(e.target.value,1,3),ratio=previous?next/previous:1;cropSession.zoom=next;cropSession.offsetX*=ratio;cropSession.offsetY*=ratio;updateCropPreview()});
document.getElementById("applyCrop").addEventListener("click",applyPhotoCrop);
document.getElementById("cropDialog").addEventListener("close",()=>{cropSession=null});
const cropViewport=document.getElementById("cropViewport");
cropViewport.addEventListener("pointerdown",e=>{if(!cropSession)return;cropSession.dragging=true;cropSession.pointerId=e.pointerId;cropSession.lastX=e.clientX;cropSession.lastY=e.clientY;cropViewport.setPointerCapture(e.pointerId);e.preventDefault()});
cropViewport.addEventListener("pointermove",e=>{if(!cropSession?.dragging||cropSession.pointerId!==e.pointerId)return;cropSession.offsetX+=e.clientX-cropSession.lastX;cropSession.offsetY+=e.clientY-cropSession.lastY;cropSession.lastX=e.clientX;cropSession.lastY=e.clientY;updateCropPreview();e.preventDefault()});
const finishCropDrag=e=>{if(!cropSession||cropSession.pointerId!==e.pointerId)return;cropSession.dragging=false;cropSession.pointerId=null};
cropViewport.addEventListener("pointerup",finishCropDrag);cropViewport.addEventListener("pointercancel",finishCropDrag);
window.addEventListener("beforeunload",()=>localStorage.setItem(STORAGE_KEY,JSON.stringify(state)));
window.NightmareRules=Object.freeze({hydrate,effectiveAttributesFor,racialBonusesFor,racialAbilityBonusesFor,automaticAttributeBonuses,automaticStatusBonuses,aggregateDefenses,derivedStatusFor,syncCombatStateFor,manaSpendPlan,calculateEffectValue,classHpBaseByTier,classHpFormula,classManaFormula,progressionClassHp,progressionClassMana,ensureProgressionState,applyPatamarChange,movementBaseFormula,skillRecordFor,skillLabelFor,skillEntriesFor,proficientSkillCount,skillBonusFor,attackModifierFor,resourcePercent,tierIndex,baseSpellCost,spellCost,spellCostBreakdown,isNativeReaction,reactionEligible,spellOmUsed,spellOmAvailable,spellDA,learningTimeDays,knownMagicStatus,resurrectionValidation,spellValidation,criticalMargin,criticalDamageExpression,parseDice,attackHitOutcome,abilityLevelWarning,uniqueLevelOptions,normalizeHybridRaces,freshActions,canSpendAction,spendAction,setDyingManual,setDeathMarkersManual,patamares:PATAMARES,spellManaByCycle:SYSTEM_CONFIG.spellManaByCycle,roundDown:SYSTEM_CONFIG.rounding});
renderApp();
